      { id: "B3_L15_EX2_1", ar: "زُوَّارٌ -> زَائِرٌ (Посетитель)", ru: "зуввар -> за'ир" },
      { id: "B3_L15_EX2_2", ar: "شِدَادٌ -> شَدِيدٌ (Сильный / суровый)", ru: "шидад -> шадид" },
      { id: "B3_L15_EX3_TITLE", ar: "٣ - هَاتِ جَمْعَ الْأَسْمَاءِ الْآتِيَةِ :", ru: "3. Приведите форму множественного числа для следующих имен:" },
      { id: "B3_L15_EX3_1", ar: "جَرِيحٌ -> جَرْحَى (Раненый)", ru: "джарих -> джарха" },
      { id: "B3_L15_EX3_2", ar: "نَفْسٌ -> أَنْفُسٌ / نُفُوسٌ (Душа)", ru: "нафс -> анфус / нуфус" },
      { id: "B3_L15_EX4_TITLE", ar: "٤ - هَاتِ ضِدَّ الْكَلِمَةِ الْآتِيَةِ :", ru: "4. Напишите антоним к следующему слову:" },
      { id: "B3_L15_EX4_1", ar: "ضَرَّ -> نَفَعَ (Приносить пользу)", ru: "дарра (вредить) -> нафа'а (приносить пользу)" },
      { id: "B3_L15_EX5_TITLE", ar: "٥ - أَدْخِلْ كُلَّ كَلِمَةٍ مِمَّا يَأْتِي فِي جُمْلَةٍ مُفِيدَةٍ :", ru: "5. Составьте содержательные предложения со следующими словами:" },
      { id: "B3_L15_EX5_1", ar: "خَالٌ (Дядя по матери): «هَذَا خَالِي مُحَمَّدٌ».", ru: "халь: «Это мой дядя по матери Мухаммад»." },
      { id: "B3_L15_EX5_2", ar: "جَرِيحٌ (Раненый): «نَقَلَ النَّاسُ الْجَرِيحَ إِلَى الْمُسْتَشْفَى».", ru: "джарих: «Люди перенесли раненого в больницу»." },
      { id: "B3_L15_EX5_3", ar: "اِسْتَقْبَلَ (Встретил): «اِسْتَقْبَلَ الرَّئِيسُ زُوَّارَهُ».", ru: "истакбаля: «Президент принял (встретил) своих посетителей»." }
